use std::{
    collections::BTreeMap,
    fs::{self, File, OpenOptions},
    path::{Path, PathBuf},
};

use anyhow::{Context, Result, bail, ensure};
use fs2::FileExt;
use serde::{Deserialize, Deserializer, Serialize, Serializer, de};
use serde_json::{Map, Value};

use crate::atomic_write;

const RECEIPT_SCHEMA: u32 = 1;
const USER_COLOR_THEME_ID: &str = "user_color_theme_id";
const MAX_COLORS_FILE_BYTES: u64 = 16 * 1024;

const OWNED_PREFS: &[&str] = &[
    "autogenerated.theme.color",
    "browser.theme.color_scheme2",
    "browser.theme.color_variant2",
    "browser.theme.follows_system_colors",
    "browser.theme.is_grayscale2",
    "browser.theme.user_color2",
    "extensions.theme.id",
    "extensions.theme.pack",
    "extensions.theme.system_theme",
];

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Rgb(u32);

impl Rgb {
    pub fn parse(value: &str) -> Result<Self> {
        ensure!(
            value.len() == 7 && value.starts_with('#'),
            "Color must use #RRGGBB"
        );
        let rgb = u32::from_str_radix(&value[1..], 16).context("Color must use #RRGGBB")?;
        Ok(Self(rgb))
    }

    fn signed_argb(self) -> i32 {
        (0xff00_0000 | self.0) as i32
    }
}

impl<'de> Deserialize<'de> for Rgb {
    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let value = String::deserialize(deserializer)?;
        Self::parse(&value).map_err(de::Error::custom)
    }
}

impl Serialize for Rgb {
    fn serialize<S>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&format!("#{:06x}", self.0))
    }
}

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum ColorScheme {
    System,
    Light,
    Dark,
}

impl ColorScheme {
    fn chrome_value(self) -> i64 {
        match self {
            Self::System => 0,
            Self::Light => 1,
            Self::Dark => 2,
        }
    }
}

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum ColorVariant {
    TonalSpot,
    Neutral,
    Vibrant,
    Expressive,
}

impl ColorVariant {
    fn chrome_value(self) -> i64 {
        match self {
            Self::TonalSpot => 1,
            Self::Neutral => 2,
            Self::Vibrant => 3,
            Self::Expressive => 4,
        }
    }
}

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct PaletteSpec {
    pub seed: Rgb,
    pub scheme: ColorScheme,
    pub variant: ColorVariant,
}

pub fn from_theme(theme: &Path) -> Result<Option<PaletteSpec>> {
    use std::io::Read;

    let path = theme.join("colors.json");
    let file = match File::open(&path) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(error).with_context(|| format!("Cannot read {}", path.display())),
    };
    let mut bytes = Vec::new();
    file.take(MAX_COLORS_FILE_BYTES + 1)
        .read_to_end(&mut bytes)?;
    ensure!(
        bytes.len() as u64 <= MAX_COLORS_FILE_BYTES,
        "colors.json must be at most 16 KiB"
    );
    serde_json::from_slice(&bytes)
        .map(Some)
        .with_context(|| format!("Invalid {}", path.display()))
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PaletteInspection {
    pub profile: PathBuf,
    pub state: PaletteState,
}

#[derive(Debug, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum PaletteState {
    Original,
    Applied,
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(tag = "state", content = "value", rename_all = "camelCase")]
enum SavedValue {
    Missing,
    Present(Value),
}

type Snapshot = BTreeMap<String, SavedValue>;

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Receipt {
    schema: u32,
    original: Snapshot,
    applied: Option<Snapshot>,
    pending: Option<Snapshot>,
}

struct PaletteStore {
    profile: PathBuf,
    preferences: PathBuf,
    receipt: PathBuf,
    _lock: File,
}

impl PaletteStore {
    fn open(profile: &Path) -> Result<Self> {
        let profile = profile
            .canonicalize()
            .context("Cannot open Chrome profile folder")?;
        ensure!(profile.is_dir(), "Select a Chrome profile folder");
        let preferences = profile.join("Preferences");
        ensure!(
            preferences.is_file(),
            "Chrome profile folder must contain Preferences"
        );
        let state = profile.join(".chromethemer");
        fs::create_dir_all(&state).context("Cannot create ChromeThemer profile state")?;
        let lock = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(state.join("palette.lock"))?;
        lock.try_lock_exclusive()
            .context("Another ChromeThemer operation is using this profile")?;
        Ok(Self {
            profile,
            preferences,
            receipt: state.join("palette.json"),
            _lock: lock,
        })
    }

    fn read_document(&self) -> Result<Value> {
        let document: Value = serde_json::from_slice(
            &fs::read(&self.preferences).context("Cannot read Chrome Preferences")?,
        )
        .context("Chrome Preferences is not valid JSON")?;
        ensure!(document.is_object(), "Chrome Preferences must be an object");
        Ok(document)
    }

    fn read_receipt(&self) -> Result<Option<Receipt>> {
        match fs::read(&self.receipt) {
            Ok(bytes) => {
                let receipt: Receipt =
                    serde_json::from_slice(&bytes).context("Invalid palette receipt")?;
                ensure!(
                    receipt.schema == RECEIPT_SCHEMA,
                    "Unsupported palette receipt schema"
                );
                Ok(Some(receipt))
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(error) => Err(error.into()),
        }
    }

    fn save_receipt(&self, receipt: &Receipt) -> Result<()> {
        atomic_write(&self.receipt, &serde_json::to_vec_pretty(receipt)?, None)
    }

    fn reconcile(&self, document: &Value, mut receipt: Receipt) -> Result<Receipt> {
        let current = snapshot(document);
        if let Some(pending) = receipt.pending.take() {
            if current == pending {
                receipt.applied = Some(pending);
            }
            self.save_receipt(&receipt)?;
        }
        Ok(receipt)
    }

    fn replace_document(&self, original: &[u8], document: &Value) -> Result<()> {
        ensure!(
            fs::read(&self.preferences)? == original,
            "Chrome Preferences changed during the operation"
        );
        let permissions = fs::metadata(&self.preferences)?.permissions();
        atomic_write(
            &self.preferences,
            &serde_json::to_vec(document)?,
            Some(permissions),
        )
    }
}

pub fn apply(profile: &Path, palette: PaletteSpec) -> Result<PaletteInspection> {
    let store = PaletteStore::open(profile)?;
    let original_bytes = fs::read(&store.preferences)?;
    let mut document = store.read_document()?;
    let current = snapshot(&document);
    let mut receipt = match store.read_receipt()? {
        Some(receipt) => store.reconcile(&document, receipt)?,
        None => Receipt {
            schema: RECEIPT_SCHEMA,
            original: current,
            applied: None,
            pending: None,
        },
    };
    let desired = desired_snapshot(palette);
    apply_snapshot(&mut document, &desired)?;
    receipt.pending = Some(desired.clone());
    store.save_receipt(&receipt)?;
    store.replace_document(&original_bytes, &document)?;
    ensure!(
        snapshot(&store.read_document()?) == desired,
        "Palette verification failed"
    );
    receipt.applied = receipt.pending.take();
    store.save_receipt(&receipt)?;
    Ok(PaletteInspection {
        profile: store.profile,
        state: PaletteState::Applied,
    })
}

pub fn restore(profile: &Path) -> Result<PaletteInspection> {
    let store = PaletteStore::open(profile)?;
    let original_bytes = fs::read(&store.preferences)?;
    let mut document = store.read_document()?;
    let Some(receipt) = store.read_receipt()? else {
        return Ok(PaletteInspection {
            profile: store.profile,
            state: PaletteState::Original,
        });
    };
    let mut receipt = store.reconcile(&document, receipt)?;
    apply_snapshot(&mut document, &receipt.original)?;
    receipt.pending = Some(receipt.original.clone());
    store.save_receipt(&receipt)?;
    store.replace_document(&original_bytes, &document)?;
    ensure!(
        snapshot(&store.read_document()?) == receipt.original,
        "Palette restore verification failed"
    );
    receipt.applied = None;
    receipt.pending = None;
    store.save_receipt(&receipt)?;
    Ok(PaletteInspection {
        profile: store.profile,
        state: PaletteState::Original,
    })
}

fn desired_snapshot(palette: PaletteSpec) -> Snapshot {
    let argb = Value::from(palette.seed.signed_argb());
    let scheme = Value::from(palette.scheme.chrome_value());
    let variant = Value::from(palette.variant.chrome_value());
    BTreeMap::from([
        ("autogenerated.theme.color".into(), SavedValue::Missing),
        (
            "browser.theme.color_scheme2".into(),
            SavedValue::Present(scheme),
        ),
        (
            "browser.theme.color_variant2".into(),
            SavedValue::Present(variant),
        ),
        (
            "browser.theme.follows_system_colors".into(),
            SavedValue::Present(Value::Bool(false)),
        ),
        (
            "browser.theme.is_grayscale2".into(),
            SavedValue::Present(Value::Bool(false)),
        ),
        (
            "browser.theme.user_color2".into(),
            SavedValue::Present(argb),
        ),
        (
            "extensions.theme.id".into(),
            SavedValue::Present(Value::String(USER_COLOR_THEME_ID.into())),
        ),
        ("extensions.theme.pack".into(), SavedValue::Missing),
        (
            "extensions.theme.system_theme".into(),
            SavedValue::Present(Value::from(0)),
        ),
    ])
}

fn snapshot(document: &Value) -> Snapshot {
    OWNED_PREFS
        .iter()
        .map(|path| {
            let value = get_path(document, path)
                .cloned()
                .map(SavedValue::Present)
                .unwrap_or(SavedValue::Missing);
            ((*path).to_owned(), value)
        })
        .collect()
}

fn get_path<'a>(document: &'a Value, path: &str) -> Option<&'a Value> {
    path.split('.')
        .try_fold(document, |value, key| value.get(key))
}

fn apply_snapshot(document: &mut Value, snapshot: &Snapshot) -> Result<()> {
    for (path, value) in snapshot {
        set_path(document, path, value.clone())?;
    }
    Ok(())
}

fn set_path(document: &mut Value, path: &str, value: SavedValue) -> Result<()> {
    let mut parts = path.split('.').peekable();
    let mut object = document
        .as_object_mut()
        .context("Chrome Preferences must be an object")?;
    while let Some(key) = parts.next() {
        if parts.peek().is_none() {
            match value {
                SavedValue::Missing => {
                    object.remove(key);
                }
                SavedValue::Present(value) => {
                    object.insert(key.to_owned(), value);
                }
            }
            return Ok(());
        }
        let child = object
            .entry(key)
            .or_insert_with(|| Value::Object(Map::new()));
        object = child
            .as_object_mut()
            .with_context(|| format!("Chrome preference parent {key} is not an object"))?;
    }
    bail!("Empty Chrome preference path")
}
